CREATE TABLE IF NOT EXISTS notifications (id bigserial PRIMARY KEY, notification_reference varchar(40) NOT NULL UNIQUE, customer_number varchar(30) NOT NULL, type varchar(30) NOT NULL, channel varchar(20) NOT NULL, title varchar(150) NOT NULL, message varchar(2000) NOT NULL, status varchar(20) NOT NULL, related_reference varchar(100), created_at timestamp NOT NULL, sent_at timestamp, read_at timestamp); CREATE INDEX IF NOT EXISTS idx_notification_customer ON notifications(customer_number); CREATE INDEX IF NOT EXISTS idx_notification_created ON notifications(created_at);
